def reverse_digits(n):
    result = 0
    while n > 0:
      result = result * 10 + n % 10
        n //= 10
    return result

def max_subarray(nums):
    best = current = nums[0]
    for x in nums[1:]:
        current = max(x, current + nums)
        best = max(best, current)
    return best

def run_length(s):
    out = []
    i = 0
    while i < len(s):
        j = i
        while j < len(s) - 1 and s[j] == s[i]:
            j += 1
        out.append(s[i] + str(j - i))
        i = j
    return "".join(out)

def two_values(nums, k):
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == k:
                return [nums[i], nums[j]]
    return []

def two_values(nums, k):
    seen = set()
    for x in nums:
        if x > k:
            continue
        if k - x in seen:
            return [k - x, x]
        seen.add(x)
    return []

from functools import lru_cache


def stairs(n):
    MOD = 10**9 + 7

    @lru_cache(maxsize=None)
    def ways(k):
        if k < 0:
            return 0
        if k == 0:
            return 1
        return (ways(k - 1) + ways(k - 2) + ways(k - 3)) % MOD

    return ways(n)

def normalize_name(s):
    words = s.split()
    fixed = []
    for w in words:
        fixed.append(w[0].upper() + w[1:].lower())
    return " ".join(fixed)
